sql_calls.sql:
SELECT sku, name, pack, gtin
FROM store.products
WHERE name ILIKE '%atta%' OR name ILIKE '%wheat%';

SELECT sku, name, pack
FROM store.products
WHERE name ILIKE '%snack%' OR name ILIKE '%chip%' OR name ILIKE '%namkeen%' OR name ILIKE '%biscuit%' OR name ILIKE '%cookie%';

SELECT sku, name, pack, flow
FROM store.products
ORDER BY name;

SELECT COUNT(*) as payment_attempts_june
FROM payments.pos_payments
WHERE bill_id LIKE 'B2606%';

SELECT SUM(revenue_inr) as total_revenue_june
FROM store.daily_sales
WHERE sale_date >= '2026-06-01' AND sale_date <= '2026-06-30';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'daily_sales';

SELECT SUM(revenue_inr) as total_revenue_june
FROM store.daily_sales
WHERE date >= '2026-06-01' AND date <= '2026-06-30';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'products';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'write_offs';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'payments' AND table_name = 'upi_settlements';

SELECT COUNT(*) as empty_count
FROM store.shelf_audits
WHERE status = 'empty' AND audit_ts >= '2026-06-01' AND audit_ts < '2026-07-01';

SELECT COUNT(*) as expired_writeoffs
FROM store.write_offs
WHERE reason = 'expired' AND writeoff_date >= '2026-06-01' AND writeoff_date < '2026-07-01';

SELECT COUNT(*) as expired_writeoffs
FROM store.write_offs
WHERE reason = 'expired' AND date >= '2026-06-01' AND date < '2026-07-01';

SELECT *
FROM store.products
WHERE sku ILIKE '%atta%' OR sku ILIKE '%ATTA%';

SELECT SUM(net_inr) as total_net_upi
FROM payments.upi_settlements
WHERE settlement_date >= '2026-06-01' AND settlement_date <= '2026-06-30';
